VERSION = "9.4.0"
_checked = {}

def _is_pinned(root):
    if root not in _checked:
        try:
            with open(os.path.join(root, "library.json")) as f:
                _checked[root] = json.load(f).get("version") == VERSION
        except Exception:
            _checked[root] = False
    return _checked[root]

def lean(env, node):
    path = node.srcnode().get_abspath().replace(os.sep, "/")
    at = path.rfind("/lvgl/src/")
    if at < 0:
        return node
    root = path[:at + len("/lvgl")]
    if path[at + len("/lvgl/"):] in SKIP and _is_pinned(root):
        return None
    return node

env.AddBuildMiddleware(lean)
